#include "RefModel.h"
struct CallerContextGuard {
 VerilatedContext* caller;
 CallerContextGuard(): caller(Verilated::threadContextp()) {}
 ~CallerContextGuard(){ Verilated::threadContextp(caller); }
};
extern "C" void ref_model_eval(unsigned long long i_clk,unsigned long long i_rst,unsigned long long i_ce,unsigned long long i_stalled_n,unsigned long long i_pc,unsigned long long i_aux,unsigned long long* o_i_ref,unsigned long long* o_pc_ref,unsigned long long* o_aux_ref,unsigned long long* o_valid_ref,unsigned long long* o_illegal_ref,unsigned long long* o_wb_cyc_ref,unsigned long long* o_wb_stb_ref,unsigned long long* o_wb_we_ref,unsigned long long* o_wb_addr_ref,unsigned long long* o_wb_data_ref,unsigned long long i_wb_ack,unsigned long long i_wb_stall,unsigned long long i_wb_err,unsigned long long i_wb_data){CallerContextGuard restore_caller;static VerilatedContext context;static RefModel model(&context);Verilated::threadContextp(&context);model.i_clk=i_clk;model.i_rst=i_rst;model.i_ce=i_ce;model.i_stalled_n=i_stalled_n;model.i_pc=i_pc;model.i_aux=i_aux;model.i_wb_ack=i_wb_ack;model.i_wb_stall=i_wb_stall;model.i_wb_err=i_wb_err;model.i_wb_data=i_wb_data;model.eval();*o_i_ref=model.o_i_ref;*o_pc_ref=model.o_pc_ref;*o_aux_ref=model.o_aux_ref;*o_valid_ref=model.o_valid_ref;*o_illegal_ref=model.o_illegal_ref;*o_wb_cyc_ref=model.o_wb_cyc_ref;*o_wb_stb_ref=model.o_wb_stb_ref;*o_wb_we_ref=model.o_wb_we_ref;*o_wb_addr_ref=model.o_wb_addr_ref;*o_wb_data_ref=model.o_wb_data_ref;}
